let cachedAtlasImg: HTMLImageElement | null = null;
let atlasLoaded = false;
const atlasListeners = new Set<() => void>();

export function getDuelCardPixelAtlas(onLoad?: () => void): HTMLImageElement | null {
  if (typeof window === "undefined") return null;
  if (atlasLoaded && cachedAtlasImg) return cachedAtlasImg;
  if (onLoad) atlasListeners.add(onLoad);
  if (!cachedAtlasImg) {
    const img = new Image();
    img.decoding = "async";
    img.onload = () => {
      atlasLoaded = true;
      atlasListeners.forEach((fn) => fn());
      atlasListeners.clear();
    };
    img.src = DUEL_CARD_ATLAS_URL;
    cachedAtlasImg = img;
  }
  return atlasLoaded ? cachedAtlasImg : null;
}
